  "resolution" text,
  "created_at" text NOT NULL,
  "updated_at" text NOT NULL,
  "started_at" text,
  "completed_at" text,
  PRIMARY KEY ("id")
);
CREATE TABLE "crm_teste"."training_progress" (
  "training_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  "first_opened_at" text,
  "last_opened_at" text,
  "open_count" bigint NOT NULL,
  "completed_at" text,
  "quiz_score" bigint,
  "attempts" bigint NOT NULL,
  PRIMARY KEY ("training_id", "user_id")
);
CREATE TABLE "crm_teste"."trainings" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "title" text NOT NULL,
  "category" text,
  "description" text,
  "kind" text NOT NULL,
  "content" text,
  "video_url" text,
  "file" bytea,
  "file_name" text,
  "file_mime" text,
  "file_size" bigint,
  "required_roles" text NOT NULL,
  "due_days" bigint,
  "quiz" text NOT NULL,
  "pass_score" bigint NOT NULL,
  "duration_min" bigint,
  "position" bigint NOT NULL,
  "active" bigint NOT NULL,
  "created_by" bigint,
  "created_at" text NOT NULL,
  "updated_at" text NOT NULL,
  "track" text,
  PRIMARY KEY ("id")
);
CREATE TABLE "crm_teste"."users" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "name" text NOT NULL,
  "email" text NOT NULL,
  "password_hash" text,
  "role" text NOT NULL,
  "team_id" bigint,
  "dialer_agent_ref" text,
