CREATE TABLE "crm_teste"."wa_conversations" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "wa_id" text NOT NULL,
  "contact_id" bigint,
  "profile_name" text,
  "assigned_to" bigint,
  "status" text NOT NULL,
  "unread" bigint NOT NULL,
