INSERT INTO "crm_teste"."pipeline_stages" ("id", "name", "position", "kind", "active", "created_at", "key", "playbook", "rot_days", "training_id") OVERRIDING SYSTEM VALUE VALUES
(1, 'Prospect', 0, 'aberta', 1, '2026-11-22T00:16:32.840Z', 'prospect', 'Contato ainda não demonstrou interesse. Objetivo: validar os dados de contato e a origem.', 3, NULL),
(2, 'Lead', 1, 'aberta', 1, '2026-11-22T00:16:32.840Z', 'lead', 'Demonstrou interesse. Objetivo: fazer o primeiro contato o quanto antes (idealmente em até 1 hora).', 1, NULL),
(3, 'Tentativa de contato', 2, 'aberta', 1, '2026-11-22T00:16:32.840Z', 'tentativa', 'Cadência de tentativas por ligação, WhatsApp, e-mail e direct até conseguir falar com o lead.', 3, NULL),
(4, 'Qualificação', 3, 'aberta', 1, '2026-11-22T00:16:32.840Z', 'qualificado', 'Conversa realizada. Objetivo: entender objetivo, valor, capacidade e prazo, e agendar a R1.', 5, NULL),
(5, 'R1', 4, 'aberta', 1, '2026-11-22T00:16:32.840Z', 'r1', 'Primeira reunião (R1): diagnóstico, apresentação da Vero e da estratégia. Cliente que não compareceu fica marcado como NS (no-show) e é remarcado.', 7, NULL),
(6, 'R2', 5, 'aberta', 1, '2026-11-22T00:16:32.840Z', 'r2', 'Segunda reunião (R2): apresentação da proposta e da estratégia montada a partir da R1, com o decisor.', 7, NULL),
(7, 'Negociação', 6, 'aberta', 1, '2026-11-22T00:16:32.840Z', 'negociacao', 'Proposta apresentada. Seguir a régua de follow-up (Dia 0 a Dia 21), ajustar a proposta e conduzir até o aceite.', 10, NULL),
(8, 'Venda', 7, 'ganho', 1, '2026-11-22T00:16:32.840Z', 'venda', 'Venda confirmada com o pagamento da primeira parcela. Entra automaticamente pela tela de Vendas.', NULL, NULL),
(9, 'Nutrição futura', 8, 'nutricao', 1, '2026-11-22T00:16:32.840Z', 'nutricao', 'Arquivado: sem momento agora. Registrar o motivo e a data para retomar o contato.', NULL, NULL),
(10, 'Perdido', 9, 'perdido', 1, '2026-11-22T00:16:32.840Z', 'perdido', 'Arquivado: negócio encerrado. O motivo da perda (MP) alimenta os relatórios.', NULL, NULL);
